def plan(config, state):
    # Compare desired config with what state says exists
    actions = []
    for name, attrs in config.items():
        if name not in state:
            actions.append("create  " + name)
        elif state[name] != attrs:
            actions.append("update  " + name)
    for name in state:
        if name not in config:
            actions.append("destroy " + name)
    return actions or ["no changes"]

config = {"web": {"size": "small"}, "db": {"size": "large"}}
state = {"web": {"size": "small"}, "db": {"size": "medium"}, "old_cache": {"size": "small"}}
print("config:", config)
print("state: ", state)
print("plan with normal state:")
for a in plan(config, state):
    print("  ", a)
print("plan after state is lost (empty state):")
for a in plan(config, {}):
    print("  ", a, "<- would duplicate a resource that already exists")

def decide(n, base_p95, canary_p95, min_n=1000, ok=1.10, bad=1.50):
    if n < min_n:
        return "HOLD (too few requests)"
    ratio = canary_p95 / base_p95
    if ratio <= ok:
        return f"PROMOTE (ratio {ratio:.2f})"
    if ratio >= bad:
        return f"ABORT (ratio {ratio:.2f})"
    return f"HOLD and gather more data (ratio {ratio:.2f})"

# (requests seen by canary, baseline p95 ms, canary p95 ms)
cases = [(300, 120, 180), (5000, 120, 126), (5000, 120, 138), (5000, 120, 200)]
for n, b, c in cases:
    print(f"n={n} baseline={b}ms canary={c}ms -> {decide(n, b, c)}")
